insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('sos','Экстренные номера','Важные телефоны и контакты для экстренных ситуаций и помощи туристам на Пхукете.','## Экстренные службы
- 191 — полиция; по данным МИД Великобритании, по этому номеру можно вызвать и скорую, и пожарных
- 1669 — скорая медицинская помощь
- 199 — пожарная служба
- 1784 — национальный центр предупреждения о бедствиях

## Туристическая и официальная помощь
- 1155 — туристическая полиция (Tourist Police Bureau)
- 1672 — информационный центр TAT для туристов (не экстренный)
- 1178 — иммиграционное бюро (визы и продление)
- Приложение Thailand Tourist Police: связь с туристической полицией онлайн, работает без тайской SIM, уведомления о бедствиях и угрозах рядом

## Медицина и страхование
- При обращении в больницу сразу свяжитесь со своей страховой/ассистансом
- Больницы в гиде: Bangkok Hospital Phuket (частная, Пхукет-Таун) и Patong Hospital (государственная, Патонг) — см. карточки мест','[{"heading_ru": "Экстренные службы", "items": [{"text_ru": "191 — полиция; по данным МИД Великобритании, по этому номеру можно вызвать и скорую, и пожарных", "sources": ["fcdo_help", "prd_numbers"], "verification": "verified"}, {"text_ru": "1669 — скорая медицинская помощь", "sources": ["fcdo_help", "prd_numbers"], "verification": "verified"}, {"text_ru": "199 — пожарная служба", "sources": ["fcdo_help"], "verification": "verified"}, {"text_ru": "1784 — национальный центр предупреждения о бедствиях", "sources": ["prd_numbers"], "verification": "verified"}]}, {"heading_ru": "Туристическая и официальная помощь", "items": [{"text_ru": "1155 — туристическая полиция (Tourist Police Bureau)", "sources": ["fcdo_help", "prd_numbers"], "verification": "verified"}, {"text_ru": "1672 — информационный центр TAT для туристов (не экстренный)", "sources": ["prd_numbers"], "verification": "verified"}, {"text_ru": "1178 — иммиграционное бюро (визы и продление)", "sources": ["prd_numbers"], "verification": "verified"}, {"text_ru": "Приложение Thailand Tourist Police: связь с туристической полицией онлайн, работает без тайской SIM, уведомления о бедствиях и угрозах рядом", "sources": ["fcdo_help"], "verification": "verified"}]}, {"heading_ru": "Медицина и страхование", "items": [{"text_ru": "При обращении в больницу сразу свяжитесь со своей страховой/ассистансом", "sources": ["fcdo_health"], "verification": "verified"}, {"text_ru": "Больницы в гиде: Bangkok Hospital Phuket (частная, Пхукет-Таун) и Patong Hospital (государственная, Патонг) — см. карточки мест", "sources": [], "verification": "internal"}]}]'::jsonb,'16plus',false,'verified',10,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.