insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('visa-entry','Въезд и виза: сроки по странам','Информация о безвизовом режиме, правилах въезда и требованиях к документам для туристов из разных стран.','## Сроки безвизового пребывания
- С 15.09.2026 60-дневный безвизовый режим отменён; срок безвизового пребывания зависит от гражданства
- Россия (общегражданский паспорт): без визы до 30 дней по двустороннему соглашению
- Казахстан: без визы до 30 календарных дней с даты въезда по межправительственному соглашению; суммарно не более 90 дней в каждом 180-дневном периоде; на срок больше 30 дней визу оформляют заранее
- Украина: без визы до 30 дней с целью туризма (список 60 стран и территорий)
- Кыргызстан: без визы до 30 дней с целью туризма (список 60 стран и территорий)

## Правила въезда и документы
- По 30-дневному безвизу из списка 60 стран (Украина, Кыргызстан) через сухопутные пункты пропуска можно въехать, как правило, не более 2 раз в календарный год
- Въехавшие до 15.09.2026 остаются до конца срока, указанного в штампе
- Для других гражданств и для виз — сайт посольства Таиланда в вашей стране и официальная система Thai e-Visa
- Безвизовый въезд — только для туризма; для работы, учёбы, длительного проживания нужна соответствующая виза до поездки
- С 1 мая 2025 все иностранцы заполняют цифровую карту прибытия TDAC онлайн до прилёта, не раньше чем за 3 дня

## Контроль, штрафы и ограничения
- На границе могут попросить подтвердить средства (10 000 бат на человека или 20 000 на семью) и обратный/дальнейший билет
- Просрочка (overstay): штраф 500 бат в день, максимум 20 000 бат; риск задержания, депортации и запрета въезда
- Паспорт: МИД Великобритании указывает срок действия не менее 6 месяцев на дату въезда — уточните требования у своей авиакомпании
- Сигареты: не более 200 шт. на человека, превышение — штраф и конфискация
- Вопросы по срокам пребывания и продлению — иммиграционное бюро, 1178','[{"heading_ru": "Сроки безвизового пребывания", "items": [{"text_ru": "С 15.09.2026 60-дневный безвизовый режим отменён; срок безвизового пребывания зависит от гражданства", "sources": ["tat_visa2026", "thaiemb_fr_pdf"], "verification": "verified"}, {"text_ru": "Россия (общегражданский паспорт): без визы до 30 дней по двустороннему соглашению", "sources": ["thaiemb_moscow", "thaiemb_fr_pdf"], "verification": "verified"}, {"text_ru": "Казахстан: без визы до 30 календарных дней с даты въезда по межправительственному соглашению; суммарно не более 90 дней в каждом 180-дневном периоде; на срок больше 30 дней визу оформляют заранее", "sources": ["govkz_phuket", "thaiemb_fr_pdf"], "verification": "verified"}, {"text_ru": "Украина: без визы до 30 дней с целью туризма (список 60 стран и территорий)", "sources": ["tat_visa2026", "thaiemb_fr_pdf"], "verification": "verified"}, {"text_ru": "Кыргызстан: без визы до 30 дней с целью туризма (список 60 стран и территорий)", "sources": ["tat_visa2026", "thaiemb_fr_pdf"], "verification": "verified"}]}, {"heading_ru": "Правила въезда и документы", "items": [{"text_ru": "По 30-дневному безвизу из списка 60 стран (Украина, Кыргызстан) через сухопутные пункты пропуска можно въехать, как правило, не более 2 раз в календарный год", "sources": ["tat_visa2026"], "verification": "verified"}, {"text_ru": "Въехавшие до 15.09.2026 остаются до конца срока, указанного в штампе", "sources": ["thaiemb_moscow"], "verification": "verified"}, {"text_ru": "Для других гражданств и для виз — сайт посольства Таиланда в вашей стране и официальная система Thai e-Visa", "sources": ["thaievisa", "tat_visa2026"], "verification": "verified"}, {"text_ru": "Безвизовый въезд — только для туризма; для работы, учёбы, длительного проживания нужна соответствующая виза до поездки", "sources": ["fcdo_entry", "tat_visa2026"], "verification": "verified"}, {"text_ru": "С 1 мая 2025 все иностранцы заполняют цифровую карту прибытия TDAC онлайн до прилёта, не раньше чем за 3 дня", "sources": ["fcdo_entry", "tdac"], "verification": "verified"}]}, {"heading_ru": "Контроль, штрафы и ограничения", "items": [{"text_ru": "На границе могут попросить подтвердить средства (10 000 бат на человека или 20 000 на семью) и обратный/дальнейший билет", "sources": ["fcdo_entry"], "verification": "verified"}, {"text_ru": "Просрочка (overstay): штраф 500 бат в день, максимум 20 000 бат; риск задержания, депортации и запрета въезда", "sources": ["fcdo_entry"], "verification": "verified"}, {"text_ru": "Паспорт: МИД Великобритании указывает срок действия не менее 6 месяцев на дату въезда — уточните требования у своей авиакомпании", "sources": ["fcdo_entry"], "verification": "verified"}, {"text_ru": "Сигареты: не более 200 шт. на человека, превышение — штраф и конфискация", "sources": ["fcdo_entry"], "verification": "verified"}, {"text_ru": "Вопросы по срокам пребывания и продлению — иммиграционное бюро, 1178", "sources": ["prd_numbers"], "verification": "verified"}]}]'::jsonb,'16plus',true,'verified',20,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
