insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('money','Деньги и оплата','Основные сведения о тайской валюте, правилах обмена, использовании карт и таможенных лимитах.','## Валюта и расчеты
- Валюта — тайский бат (THB)
- Если терминал или банкомат предлагает списать в валюте вашей карты — выбирайте баты
- Наличные по-прежнему нужны: уличная еда, рынки
- Карты российских банков в Таиланде работают только через UnionPay

## Безопасность и обмен валюты
- Пользуйтесь банкоматами в отделениях банков, прикрывайте PIN, не выпускайте карту из виду — бывают скимминг и мошенничество с картами
- Обменять валюту можно в банке или у лицензированного обменника (Authorized Money Changer): по закону обмен валюты ведут только лица с лицензией Минфина Таиланда
- В туристических районах Пхукета (Патонг, Пхукет-Таун, торговые центры) много обменных пунктов; при обмене просят паспорт; сравнивайте итоговую сумму в батах, а не только курс

## Таможенные правила и лимиты
- Ввоз/вывоз иностранной валюты свыше эквивалента 20 000 USD нужно декларировать на таможне; недекларирование — уголовное правонарушение
- Вывоз бат: до 50 000 бат (в соседние страны — до 500 000) без декларации','[{"heading_ru": "Валюта и расчеты", "items": [{"text_ru": "Валюта — тайский бат (THB)", "sources": ["thp"], "verification": "verified"}, {"text_ru": "Если терминал или банкомат предлагает списать в валюте вашей карты — выбирайте баты", "sources": ["vt_cards"], "verification": "verified"}, {"text_ru": "Наличные по-прежнему нужны: уличная еда, рынки", "sources": ["vt_cards"], "verification": "verified"}, {"text_ru": "Карты российских банков в Таиланде работают только через UnionPay", "sources": ["owner"], "verification": "owner_confirmed"}]}, {"heading_ru": "Безопасность и обмен валюты", "items": [{"text_ru": "Пользуйтесь банкоматами в отделениях банков, прикрывайте PIN, не выпускайте карту из виду — бывают скимминг и мошенничество с картами", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Обменять валюту можно в банке или у лицензированного обменника (Authorized Money Changer): по закону обмен валюты ведут только лица с лицензией Минфина Таиланда", "sources": ["bot_fx"], "verification": "verified"}, {"text_ru": "В туристических районах Пхукета (Патонг, Пхукет-Таун, торговые центры) много обменных пунктов; при обмене просят паспорт; сравнивайте итоговую сумму в батах, а не только курс", "sources": ["phuketanchor_fx"], "verification": "verified"}]}, {"heading_ru": "Таможенные правила и лимиты", "items": [{"text_ru": "Ввоз/вывоз иностранной валюты свыше эквивалента 20 000 USD нужно декларировать на таможне; недекларирование — уголовное правонарушение", "sources": ["thaiemb_london_currency", "customs"], "verification": "verified"}, {"text_ru": "Вывоз бат: до 50 000 бат (в соседние страны — до 500 000) без декларации", "sources": ["thaiemb_london_currency"], "verification": "verified"}]}]'::jsonb,'16plus',true,'verified',30,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
