insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('connectivity','Связь: SIM и eSIM','Правила приобретения и использования местной и зарубежной связи на Пхукете.','## Регистрация местной SIM-карты
- Тайская туристическая SIM/eSIM (AIS, True/dtac) регистрируется на оригинал паспорта; с 18.08.2025 при регистрации обязательна проверка лица (liveness) (требует проверки)
- Туристическая SIM работает не более 60 дней с активации, пополнение не продлевает; дальше — повторная проверка личности у оператора (требует проверки)
- Не более 3 номеров на человека у одного оператора; каждому члену семьи нужен свой паспорт (требует проверки)

## Альтернативная связь и безопасность
- Туристическая data-eSIM от зарубежного продавца даёт только интернет, без тайского номера, регистрация в Таиланде обычно не нужна (требует проверки)
- Не отправляйте фото паспорта и селфи неофициальным продавцам
- Приложение Thailand Tourist Police работает без тайской SIM','[{"heading_ru": "Регистрация местной SIM-карты", "items": [{"text_ru": "Тайская туристическая SIM/eSIM (AIS, True/dtac) регистрируется на оригинал паспорта; с 18.08.2025 при регистрации обязательна проверка лица (liveness) (требует проверки)", "sources": ["sim_kyc", "sim_60"], "verification": "needs_check", "needs_check_note": "Правила NBTC взяты из вторичных источников (CORAL eSIM, OpenSim со ссылкой на PRD/NBTC); официальные страницы AIS/True/NBTC не открыты"}, {"text_ru": "Туристическая SIM работает не более 60 дней с активации, пополнение не продлевает; дальше — повторная проверка личности у оператора (требует проверки)", "sources": ["sim_60", "sim_kyc"], "verification": "needs_check", "needs_check_note": "то же: вторичные источники"}, {"text_ru": "Не более 3 номеров на человека у одного оператора; каждому члену семьи нужен свой паспорт (требует проверки)", "sources": ["sim_kyc", "sim_60"], "verification": "needs_check", "needs_check_note": "то же: вторичные источники"}]}, {"heading_ru": "Альтернативная связь и безопасность", "items": [{"text_ru": "Туристическая data-eSIM от зарубежного продавца даёт только интернет, без тайского номера, регистрация в Таиланде обычно не нужна (требует проверки)", "sources": ["sim_60"], "verification": "needs_check", "needs_check_note": "вторичный источник"}, {"text_ru": "Не отправляйте фото паспорта и селфи неофициальным продавцам", "sources": ["sim_kyc"], "verification": "verified"}, {"text_ru": "Приложение Thailand Tourist Police работает без тайской SIM", "sources": ["fcdo_help"], "verification": "verified"}]}]'::jsonb,'16plus',false,'partially_verified',40,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
