insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('transport','Транспорт и трансфер из аэропорта','Способы передвижения по Пхукету и правила использования транспорта из аэропорта.','## Официальный транспорт в аэропорту
- В аэропорту пользуйтесь только официальным транспортом из отведённых зон; тарифы установлены Phuket Provincial Land Transport Office, их можно проверить до поездки
- Аэропорт в ноябре 2026 усилил патрули из-за нелегальных зазывал-таксистов; неофициальный транспорт — риск переплаты и безопасности
- Прокат авто — стойки в аэропорту
- Актуальные расписания и тарифы автобусов смотрите на официальных сайтах — в гиде мы их не дублируем

## Автобусы и минивэны
- Airport Bus: аэропорт — город (Phuket Town), у выхода из зала прилёта
- Airport Bus Express: аэропорт — Патонг
- Phuket Smart Bus: остановка у внутреннего терминала, маршрут вдоль западного побережья (Surin, Kamala, Patong, Karon, Kata) до Rawai; на сайте есть расписание и GPS-отслеживание
- Общественные минивэны из аэропорта до Патонга, Каты и Карона

## Городские поездки и безопасность
- Grab и Bolt работают на Пхукете (в Bolt есть категория Taxi)
- В открытом транспорте (тук-тук) берегите вещи; заранее планируйте дорогу домой вечером, не садитесь в нелицензированные машины','[{"heading_ru": "Официальный транспорт в аэропорту", "items": [{"text_ru": "В аэропорту пользуйтесь только официальным транспортом из отведённых зон; тарифы установлены Phuket Provincial Land Transport Office, их можно проверить до поездки", "sources": ["phuketnews_touts"], "verification": "verified"}, {"text_ru": "Аэропорт в ноябре 2026 усилил патрули из-за нелегальных зазывал-таксистов; неофициальный транспорт — риск переплаты и безопасности", "sources": ["phuketnews_touts"], "verification": "verified"}, {"text_ru": "Прокат авто — стойки в аэропорту", "sources": ["aot_hkt"], "verification": "verified"}, {"text_ru": "Актуальные расписания и тарифы автобусов смотрите на официальных сайтах — в гиде мы их не дублируем", "sources": [], "verification": "internal"}]}, {"heading_ru": "Автобусы и минивэны", "items": [{"text_ru": "Airport Bus: аэропорт — город (Phuket Town), у выхода из зала прилёта", "sources": ["aot_hkt"], "verification": "verified"}, {"text_ru": "Airport Bus Express: аэропорт — Патонг", "sources": ["aot_hkt"], "verification": "verified"}, {"text_ru": "Phuket Smart Bus: остановка у внутреннего терминала, маршрут вдоль западного побережья (Surin, Kamala, Patong, Karon, Kata) до Rawai; на сайте есть расписание и GPS-отслеживание", "sources": ["aot_hkt", "smartbus"], "verification": "verified"}, {"text_ru": "Общественные минивэны из аэропорта до Патонга, Каты и Карона", "sources": ["aot_hkt"], "verification": "verified"}]}, {"heading_ru": "Городские поездки и безопасность", "items": [{"text_ru": "Grab и Bolt работают на Пхукете (в Bolt есть категория Taxi)", "sources": ["grab", "bolt"], "verification": "verified"}, {"text_ru": "В открытом транспорте (тук-тук) берегите вещи; заранее планируйте дорогу домой вечером, не садитесь в нелицензированные машины", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',false,'verified',50,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
