insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('scooter','Скутер: права, шлем, страховка','Важные требования и риски при аренде и вождении скутера в Таиланде.','## Документы и правила вождения
- По закону шлем обязателен
- Нужны действующие национальные права нужной категории и международное водительское удостоверение (МВУ); МИД Великобритании, например, требует МВУ образца 1968 г. — проверьте, какой образец нужен для вашей страны
- Езда без действующих прав может сделать страховку недействительной

## Аренда и безопасность
- Арендные мотоциклы в туристических зонах часто не зарегистрированы и не могут легально ездить по дорогам; читайте договор, проверьте страховку (объём двигателя, категория)
- Не оставляйте паспорт в залог — его могут удерживать под предлогом повреждений
- В Таиланде много ДТП, особенно с мотоциклами (данные ВОЗ)','[{"heading_ru": "Документы и правила вождения", "items": [{"text_ru": "По закону шлем обязателен", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Нужны действующие национальные права нужной категории и международное водительское удостоверение (МВУ); МИД Великобритании, например, требует МВУ образца 1968 г. — проверьте, какой образец нужен для вашей страны", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Езда без действующих прав может сделать страховку недействительной", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Аренда и безопасность", "items": [{"text_ru": "Арендные мотоциклы в туристических зонах часто не зарегистрированы и не могут легально ездить по дорогам; читайте договор, проверьте страховку (объём двигателя, категория)", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Не оставляйте паспорт в залог — его могут удерживать под предлогом повреждений", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "В Таиланде много ДТП, особенно с мотоциклами (данные ВОЗ)", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',true,'verified',60,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
