insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('sea-safety','Море и пляжи: флаги, течения, муссон','Правила безопасности на воде, информация о течениях, флагах и погодных условиях на Пхукете.','## Муссон и течения
- Юго-западный муссон на Пхукете — май–октябрь: сильные волны и смертельно опасные отбойные течения (rip currents)
- Купайтесь у пляжей со спасателями, соблюдайте флаги; красный флаг — купаться нельзя
- Сезон дождей в целом май–октябрь; следите за предупреждениями Thai Meteorological Department

## Статистика и происшествия
- По данным PPAO, за 2024–2026 гг. на Пхукете утонули 56 человек; больше всего — на Karon (20), затем Kata и Surin (по 5), Patong и Mai Khao (по 4)
- Медузы подходят к берегу, особенно в сезон дождей (май–октябрь); ожоги могут быть смертельными — спрашивайте в отеле и дайв-центрах
- Катера и паромы: аварии из-за перегруза, плохого обслуживания и шторма, особенно в муссон

## Дайвинг
- Дайвинг: проверяйте документы оператора, состояние снаряжения, наличие кислорода на лодке, условия страховки','[{"heading_ru": "Муссон и течения", "items": [{"text_ru": "Юго-западный муссон на Пхукете — май–октябрь: сильные волны и смертельно опасные отбойные течения (rip currents)", "sources": ["phuketnews_drown", "fcdo_safety"], "verification": "verified"}, {"text_ru": "Купайтесь у пляжей со спасателями, соблюдайте флаги; красный флаг — купаться нельзя", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Сезон дождей в целом май–октябрь; следите за предупреждениями Thai Meteorological Department", "sources": ["fcdo_safety", "tmd"], "verification": "verified"}]}, {"heading_ru": "Статистика и происшествия", "items": [{"text_ru": "По данным PPAO, за 2024–2026 гг. на Пхукете утонули 56 человек; больше всего — на Karon (20), затем Kata и Surin (по 5), Patong и Mai Khao (по 4)", "sources": ["phuketnews_drown"], "verification": "verified"}, {"text_ru": "Медузы подходят к берегу, особенно в сезон дождей (май–октябрь); ожоги могут быть смертельными — спрашивайте в отеле и дайв-центрах", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Катера и паромы: аварии из-за перегруза, плохого обслуживания и шторма, особенно в муссон", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Дайвинг", "items": [{"text_ru": "Дайвинг: проверяйте документы оператора, состояние снаряжения, наличие кислорода на лодке, условия страховки", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',false,'verified',70,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
