insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('health-insurance','Здоровье и страховка','Медицинские рекомендации, страхование и риски для здоровья во время поездки.','## Медицинское обслуживание
- Оформите страховку на лечение и экстренную эвакуацию
- Больницы требуют гарантию оплаты до лечения
- Частные больницы высокого уровня, но дорогие
- Скутер без прав и экстремальные активности могут не покрываться страховкой — читайте условия

## Риски и профилактика
- Прививки и риски проверьте минимум за 8 недель до поездки (TravelHealthPro)
- Есть риск денге (комары кусают днём); бешенство

## Лекарства и еда
- Статус некоторых лекарств в Таиланде отличается; лекарства с улицы могут быть поддельными
- Отравления метанолом в алкогольных напитках — по вкусу и запаху не определить; при симптомах срочно к врачу','[{"heading_ru": "Медицинское обслуживание", "items": [{"text_ru": "Оформите страховку на лечение и экстренную эвакуацию", "sources": ["fcdo_health"], "verification": "verified"}, {"text_ru": "Больницы требуют гарантию оплаты до лечения", "sources": ["fcdo_health"], "verification": "verified"}, {"text_ru": "Частные больницы высокого уровня, но дорогие", "sources": ["fcdo_health"], "verification": "verified"}, {"text_ru": "Скутер без прав и экстремальные активности могут не покрываться страховкой — читайте условия", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Риски и профилактика", "items": [{"text_ru": "Прививки и риски проверьте минимум за 8 недель до поездки (TravelHealthPro)", "sources": ["fcdo_health", "thp"], "verification": "verified"}, {"text_ru": "Есть риск денге (комары кусают днём); бешенство", "sources": ["fcdo_health", "thp"], "verification": "verified"}]}, {"heading_ru": "Лекарства и еда", "items": [{"text_ru": "Статус некоторых лекарств в Таиланде отличается; лекарства с улицы могут быть поддельными", "sources": ["fcdo_health"], "verification": "verified"}, {"text_ru": "Отравления метанолом в алкогольных напитках — по вкусу и запаху не определить; при симптомах срочно к врачу", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',false,'verified',80,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
