insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('safety','Безопасность: основное','Основные правила личной безопасности, документы и законы в Таиланде.','## Личная безопасность
- Берегите вещи от карманников и выхватывания сумок с мотоциклов
- Не оставляйте напитки без присмотра, не принимайте напитки от незнакомцев
- Ночью не ходите в одиночку по безлюдным местам

## Документы и законы
- Полиция может попросить паспорт; обычно достаточно копии страницы с фото, иначе придётся предъявить в участке в течение 24 часов
- Избегайте протестов и политических собраний
- С 28.08.2026 иностранца могут депортировать без приговора, если власти сочтут поведение противоречащим общественному порядку или морали','[{"heading_ru": "Личная безопасность", "items": [{"text_ru": "Берегите вещи от карманников и выхватывания сумок с мотоциклов", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Не оставляйте напитки без присмотра, не принимайте напитки от незнакомцев", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Ночью не ходите в одиночку по безлюдным местам", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Документы и законы", "items": [{"text_ru": "Полиция может попросить паспорт; обычно достаточно копии страницы с фото, иначе придётся предъявить в участке в течение 24 часов", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Избегайте протестов и политических собраний", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "С 28.08.2026 иностранца могут депортировать без приговора, если власти сочтут поведение противоречащим общественному порядку или морали", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',true,'verified',90,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
