insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('laws-etiquette','Законы и этикет','Правила поведения, законы и ограничения на Пхукете для туристов.','## Правила в храмах и этикет
- В храмах необходимы закрытые плечи и колени
- Обувь снимают перед входом в здания
- Ноги не направляют на изображения Будды
- Критика монархии (lèse-majesté) — уголовное преступление, срок большой; касается и публикаций в соцсетях

## Запреты и ограничения
- Вейпы, электронные сигареты, жидкости и устройства heat-not-burn запрещены: хранение и использование; штрафы обычно 5 000–30 000 бат, задержание; исключений для туристов нет
- Курение в общественных местах запрещено, штраф до 5 000 бат
- Каннабис — только по медицинскому рецепту Таиланда; рекреационное употребление незаконно; вывоз запрещён
- Наркотики: суровые наказания, вплоть до смертной казни за класс A

## Алкоголь, транспорт и ввоз
- Продажа алкоголя ограничена с полуночи до 11:00 (кроме лицензированных отелей, аэропортов и разрешённых заведений)
- Дрон нужно зарегистрировать в NBTC в течение 30 дней после въезда
- Нельзя ввозить/иметь при себе более 120 игральных карт
- Публикация фото с алкоголем или в неподобающей одежде может быть незаконной
- Покупка и продажа охраняемых диких животных и их частей без лицензии запрещена','[{"heading_ru": "Правила в храмах и этикет", "items": [{"text_ru": "В храмах необходимы закрытые плечи и колени", "sources": ["vt_temple", "tat_temple"], "verification": "verified"}, {"text_ru": "Обувь снимают перед входом в здания", "sources": ["vt_temple", "tat_temple"], "verification": "verified"}, {"text_ru": "Ноги не направляют на изображения Будды", "sources": ["vt_temple", "tat_temple"], "verification": "verified"}, {"text_ru": "Критика монархии (lèse-majesté) — уголовное преступление, срок большой; касается и публикаций в соцсетях", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Запреты и ограничения", "items": [{"text_ru": "Вейпы, электронные сигареты, жидкости и устройства heat-not-burn запрещены: хранение и использование; штрафы обычно 5 000–30 000 бат, задержание; исключений для туристов нет", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Курение в общественных местах запрещено, штраф до 5 000 бат", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Каннабис — только по медицинскому рецепту Таиланда; рекреационное употребление незаконно; вывоз запрещён", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Наркотики: суровые наказания, вплоть до смертной казни за класс A", "sources": ["fcdo_safety"], "verification": "verified"}]}, {"heading_ru": "Алкоголь, транспорт и ввоз", "items": [{"text_ru": "Продажа алкоголя ограничена с полуночи до 11:00 (кроме лицензированных отелей, аэропортов и разрешённых заведений)", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Дрон нужно зарегистрировать в NBTC в течение 30 дней после въезда", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Нельзя ввозить/иметь при себе более 120 игральных карт", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Публикация фото с алкоголем или в неподобающей одежде может быть незаконной", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Покупка и продажа охраняемых диких животных и их частей без лицензии запрещена", "sources": ["fcdo_safety"], "verification": "verified"}]}]'::jsonb,'16plus',true,'verified',100,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
