insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('scams','Мошенничество: чего избегать','Основные схемы обмана и способы защиты от мошенников на Пхукете.','## Аренда и транспорт
- Аренда гидроцикла или мотоцикла: не оставляйте паспорт в залог, его удерживают под предлогом повреждений
- Нелегальные зазывалы-таксисты в аэропорту — пользуйтесь официальным транспортом из отведённых зон

## Финансы и трудоустройство
- Скимминг и мошенничество с картами — банкоматы в отделениях банков, прикрывайте PIN
- Предложения работы «слишком хорошие, чтобы быть правдой» — людей вывозили в соседние страны и принуждали к онлайн-мошенничеству
- Не передавайте фото паспорта и селфи неофициальным продавцам SIM

## Экстренная помощь
- При спорах с прокатом, такси или заведением звоните в туристическую полицию 1155','[{"heading_ru": "Аренда и транспорт", "items": [{"text_ru": "Аренда гидроцикла или мотоцикла: не оставляйте паспорт в залог, его удерживают под предлогом повреждений", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Нелегальные зазывалы-таксисты в аэропорту — пользуйтесь официальным транспортом из отведённых зон", "sources": ["phuketnews_touts"], "verification": "verified"}]}, {"heading_ru": "Финансы и трудоустройство", "items": [{"text_ru": "Скимминг и мошенничество с картами — банкоматы в отделениях банков, прикрывайте PIN", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Предложения работы «слишком хорошие, чтобы быть правдой» — людей вывозили в соседние страны и принуждали к онлайн-мошенничеству", "sources": ["fcdo_safety"], "verification": "verified"}, {"text_ru": "Не передавайте фото паспорта и селфи неофициальным продавцам SIM", "sources": ["sim_kyc"], "verification": "verified"}]}, {"heading_ru": "Экстренная помощь", "items": [{"text_ru": "При спорах с прокатом, такси или заведением звоните в туристическую полицию 1155", "sources": ["fcdo_help", "prd_numbers"], "verification": "verified"}]}]'::jsonb,'16plus',false,'verified',110,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
