insert into public.practical_topics (slug,title,summary_ru,body_md,sections,direction,legal_flag,verification_status,sort_order,is_published,verified_at) values ('apps','Полезные приложения и сайты','Список официальных сайтов и мобильных приложений для туристов на Пхукете.','## Транспорт и поездки
- Grab — такси и доставка, работает на Пхукете
- Bolt — заказ машины и такси на Пхукете
- Phuket Smart Bus — расписание и GPS-отслеживание автобуса на официальном сайте

## Документы и безопасность
- Thailand Tourist Police — связь с туристической полицией, работает без тайской SIM
- TDAC — официальный сайт цифровой карты прибытия (заполняется онлайн)
- Thai e-Visa — официальная система визовых заявлений

## Погода
- Thai Meteorological Department — официальные предупреждения о погоде','[{"heading_ru": "Транспорт и поездки", "items": [{"text_ru": "Grab — такси и доставка, работает на Пхукете", "sources": ["grab"], "verification": "verified"}, {"text_ru": "Bolt — заказ машины и такси на Пхукете", "sources": ["bolt"], "verification": "verified"}, {"text_ru": "Phuket Smart Bus — расписание и GPS-отслеживание автобуса на официальном сайте", "sources": ["smartbus"], "verification": "verified"}]}, {"heading_ru": "Документы и безопасность", "items": [{"text_ru": "Thailand Tourist Police — связь с туристической полицией, работает без тайской SIM", "sources": ["fcdo_help"], "verification": "verified"}, {"text_ru": "TDAC — официальный сайт цифровой карты прибытия (заполняется онлайн)", "sources": ["tdac"], "verification": "verified"}, {"text_ru": "Thai e-Visa — официальная система визовых заявлений", "sources": ["thaievisa"], "verification": "verified"}]}, {"heading_ru": "Погода", "items": [{"text_ru": "Thai Meteorological Department — официальные предупреждения о погоде", "sources": ["tmd"], "verification": "verified"}]}]'::jsonb,'16plus',false,'verified',120,false,'2026-11-24') on conflict (slug) do update set title=excluded.title,summary_ru=excluded.summary_ru,body_md=excluded.body_md,sections=excluded.sections,legal_flag=excluded.legal_flag,verification_status=excluded.verification_status,sort_order=excluded.sort_order,verified_at=excluded.verified_at,updated_at=now();
