insert into public.affiliate_placements (slot_key,program_key,placement_type,affiliate_link_id,practical_slug,direction,title_ru,body_ru,cta_ru,disclosure_label_ru,disclosure_ru,sort_order,is_active) select 'practical:money:owner-exchange','owner_exchange','practical_page',(select id from public.affiliate_links where notes='program_key=owner_exchange' limit 1),'money','16plus','Обмен валюты на Пхукете','Сервис YELOO (Telegram) принимает RUB, USD, KZT, UAH и USDT. Доступна оплата переводом или наличными, получение бат наличными или снятие в банкомате. Бонус по нашей ссылке: при одном обмене от 106 USD вы получаете 100 бат (начисляются в эквиваленте USD), вывод бонуса — через @yeloo_support по будням 13:00–22:00 по времени Таиланда.','Открыть YELOO','Партнёр','Этот сервис является партнером путеводителя, и редакция может получать вознаграждение.',10,true on conflict (slot_key) do update set affiliate_link_id=excluded.affiliate_link_id,title_ru=excluded.title_ru,body_ru=excluded.body_ru,cta_ru=excluded.cta_ru,disclosure_label_ru=excluded.disclosure_label_ru,disclosure_ru=excluded.disclosure_ru,is_active=true;
